import { Component, ChangeDetectionStrategy, signal, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule, FormBuilder, FormGroup } from '@angular/forms';
import { MatIconModule } from '@angular/material/icon';
import { ScheconPageLayoutComponent } from '../../../../shared/components/schecon-page-layout/schecon-page-layout.component';
import { CalendarWeekViewMiniComponent } from '../../../../shared/components/calendar-week-view-mini/calendar-week-view-mini.component';
import { NotificationService } from '../../../../shared/services/notification.service';

interface CandidateSlot {
  date: string;
  dayOfWeek: string;
  timeRange: string;
  checked: boolean;
}

@Component({
  selector: 'app-confirm-page',
  standalone: true,
  imports: [CommonModule, FormsModule, ReactiveFormsModule, MatIconModule, ScheconPageLayoutComponent, CalendarWeekViewMiniComponent],
  templateUrl: './confirm-page.component.html',
  styleUrl: './confirm-page.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ConfirmPageComponent {
  conditionForm: FormGroup;
  includeWeekends = signal(false);
  includeAllDay = signal(true);
  candidateSlots = signal<CandidateSlot[]>(this.generateMockSlots());
  checkedCount = computed(() => this.candidateSlots().filter(s => s.checked).length);

  organizers = ['ishizawamoph@gmail.com', '山田太郎', '佐藤花子'];

  constructor(private fb: FormBuilder, private notification: NotificationService) {
    this.conditionForm = this.fb.group({
      organizer: ['ishizawamoph@gmail.com'],
      hideParticipantNames: [false],
      period: ['2weeks'],
      timeSlot: ['meeting'],
      duration: ['60'],
      travelTime: ['none'],
    });
  }

  toggleSlot(index: number): void {
    this.candidateSlots.update(slots =>
      slots.map((s, i) => i === index ? { ...s, checked: !s.checked } : s)
    );
  }

  copyAsText(): void {
    const text = this.candidateSlots().filter(s => s.checked).map(s => `${s.date}(${s.dayOfWeek}) ${s.timeRange}`).join('\n');
    navigator.clipboard.writeText(text);
    this.notification.success('候補日時をコピーしました');
  }

  copyInvitation(): void { this.notification.success('招待文をコピーしました'); }
  shareByMail(): void { this.notification.info('メールで共有します'); }
  shareBySlack(): void { this.notification.info('Slackで共有します'); }
  shareByChatwork(): void { this.notification.info('Chatworkで共有します'); }

  onCreate(): void { this.notification.success('空き時間から予定調整を作成しました'); }

  private generateMockSlots(): CandidateSlot[] {
    return [
      { date: '04/07', dayOfWeek: '火', timeRange: '09:30 - 11:30', checked: true },
      { date: '04/08', dayOfWeek: '水', timeRange: '14:00 - 16:00', checked: true },
      { date: '04/09', dayOfWeek: '木', timeRange: '09:30 - 10:30', checked: true },
      { date: '04/09', dayOfWeek: '木', timeRange: '14:00 - 18:30', checked: true },
      { date: '04/10', dayOfWeek: '金', timeRange: '16:00 - 19:00', checked: true },
      { date: '04/13', dayOfWeek: '月', timeRange: '12:30 - 13:30', checked: true },
      { date: '04/13', dayOfWeek: '月', timeRange: '16:00 - 18:00', checked: true },
      { date: '04/14', dayOfWeek: '火', timeRange: '09:30 - 13:30', checked: true },
      { date: '04/15', dayOfWeek: '水', timeRange: '12:30 - 13:30', checked: true },
      { date: '04/15', dayOfWeek: '水', timeRange: '16:30 - 19:00', checked: true },
      { date: '04/16', dayOfWeek: '木', timeRange: '09:30 - 10:30', checked: true },
      { date: '04/16', dayOfWeek: '木', timeRange: '12:30 - 18:30', checked: true },
      { date: '04/17', dayOfWeek: '金', timeRange: '09:30 - 10:30', checked: true },
      { date: '04/17', dayOfWeek: '金', timeRange: '12:30 - 13:30', checked: true },
      { date: '04/17', dayOfWeek: '金', timeRange: '17:30 - 18:30', checked: true },
    ];
  }
}
